import Image, { type ImageProps } from 'next/image';

// Covers whose mocha backdrop has a Barbie-night (plum) twin in /work-night.
// Generated by portfolio-showcase/tools/night_covers.py; only the backdrop is
// recoloured, the screenshots are untouched.
const NIGHT = new Set(['cackle-wide.jpg','cover-automated-newsletter.jpg','cover-autonomous-thought-leadership.jpg','cover-crm-call-intelligence.jpg','cover-demand-automation-network.jpg','cover-intelligent-distribution.jpg','cover-multi-category-editorial.jpg','cover-omnichannel-creative.jpg','cover-self-healing-content.jpg','cover-udm-booking-system.jpg','cover-vapehub.jpg','octi-wide.jpg','voice-receptionist.jpg']);

// Drop-in for next/image. At night it shows the plum twin instead. The hidden
// one is display:none, so a lazy image never downloads until its theme is on.
export default function ThemedImage(props: ImageProps) {
  const src = typeof props.src === 'string' ? props.src : null;
  const name = src?.startsWith('/work/') ? src.slice(6) : null;
  if (!name || !NIGHT.has(name)) return <Image {...props} alt={props.alt} />;
  const cls = props.className ?? '';
  return (
    <>
      <Image {...props} alt={props.alt} className={`day-only ${cls}`} />
      <Image {...props} alt={props.alt} src={`/work-night/${name}`} priority={false} className={`night-only ${cls}`} />
    </>
  );
}
